public class ByteViewerLocationMemento : LocationMemento {
	protected static readonly string BLOCK_NUM = "Block Num";
	protected static readonly string BLOCK_OFFSET = "Block Offset";

	private ViewerPosition viewerPosition;
	private int blockNum;
	private BigInteger blockOffset;
	private int column;

	public ByteViewerLocationMemento(Program program, ProgramLocation location, int blockNum,
			BigInteger blockOffset, int column, ViewerPosition viewerPosition) : base(program, location)
    {
		this.blockNum = blockNum;
		this.blockOffset = blockOffset;
		this.viewerPosition = viewerPosition;
		this.column = column;
	}

	public ByteViewerLocationMemento(SaveState saveState, Program[] programs) : base(saveState, programs)
    {
		blockNum = saveState.getInt(BLOCK_NUM, 0);
		blockOffset = new BigInteger(saveState.getString(BLOCK_OFFSET, "0"));
		int index = saveState.getInt("INDEX", 0);
		int yOffset = saveState.getInt("Y_OFFSET", 0);
		int xOffset = saveState.getInt("X_OFFSET", 0);
		viewerPosition = new ViewerPosition(index, xOffset, yOffset);
	}

